{"command": "ls /work/workspace/documents/*.csv /work/CONTRACT.md /work/workspace/library/INDEX.md 2>&1
python3 - <<'EOF'
import re, glob, os
whitelist = {re.match(r"\|\s*`([^`]+)`", l).group(1)
             for l in open("/work/workspace/library/INDEX.md") if re.match(r"\|\s*`", l)}
records  = {os.path.basename(p) for p in glob.glob("/work/workspace/documents/**/*.*", recursive=True)}
env      = {os.path.basename(p) for p in ["/work/CONTRACT.md", "/work/workspace/library/INDEX.md"]}
engagement = {os.path.basename(p) for p in glob.glob("/work/workspace/deliverable/**/*.*", recursive=True)}
allowed = whitelist | records | env | engagement
bad = 0
for path in sorted(glob.glob("/work/workspace/deliverable/**/*.md", recursive=True) +
                   glob.glob("/work/workspace/deliverable/**/*.json", recursive=True) +
                   glob.glob("/work/workspace/deliverable/**/*.csv", recursive=True)):
    txt = open(path).read()
    cited = set(re.findall(r"`([A-Za-z0-9_]+\.(?:md|json|csv))`", txt)) | set(re.findall(r"(?<![`\w])([A-Za-z0-9_]+\.(?:md|json|csv))\b", txt))
    strays = cited - allowed
    if strays:
        bad += 1; print(f"  STRAY {path}: {strays}")
print("final citation sweep:", "PASS" if not bad else "FAIL")
EOF"}
